function demoMain(idx,label){
  var samples=['{"a":1}',"{'b':'x'}","[1,2,3]"];
  var s=samples[idx%samples.length];
  return "["+label+"] inferred type for "+s+" -> "+(s[0]==="["?"number[]":s.indexOf("a")>=0?"{a:number}":"{b:string}");
}

